class Solution:
    def maxSubstrings(self, word: str) -> int:
        last = {}
        cnt, lastEnd = 0, -1
        for i, c in enumerate(word):
            if c in last and i - last[c] >= 3 and last[c] > lastEnd:
                cnt += 1
                lastEnd = i
            last[c] = i
        return cnt

c.cpp:
class Solution {
public:
    int maxSubstrings(string word) {
        int last[26]; fill(last, last + 26, -1);
        int cnt = 0, lastEnd = -1;
        for (int i = 0; i < (int)word.size(); i++) {
            int c = word[i] - 'a';
            if (last[c] >= 0 && i - last[c] >= 3 && last[c] > lastEnd) {
                cnt++;
                lastEnd = i;
            }
            last[c] = i;
        }
        return cnt;
    }
};

