class Solution {
    public int maxSubstrings(String word) {
        int[] last = new int[26];
        java.util.Arrays.fill(last, -1);
        int cnt = 0, lastEnd = -1;
        for (int i = 0; i < word.length(); i++) {
            int c = word.charAt(i) - 'a';
            if (last[c] >= 0 && i - last[c] >= 3 && last[c] > lastEnd) {
                cnt++;
                lastEnd = i;
            }
            last[c] = i;
        }
        return cnt;
    }
}

