var maxSubstrings = function(word) {
    const last = {};
    let cnt = 0, lastEnd = -1;
    for (let i = 0; i < word.length; i++) {
        const c = word[i];
        if (last[c] !== undefined && i - last[c] >= 3 && last[c] > lastEnd) {
            cnt++;
            lastEnd = i;
        }
        last[c] = i;
    }
    return cnt;
};
